-- Sport & Gesundheit (04.11.2026): Grundbestand um Dehnübungen für alle Muskelgruppen (auch die oft vernachlässigten)
-- und Reha-Übungen erweitert, darunter ein Block für Shin Splints. Rein additiv; gibt es einen Namen im Grundbestand
-- schon, bleibt er unverändert.

insert into public.exercises (name, muscle_group, secondary_muscles, equipment, tracking, category, instructions, created_by)
select v.name, v.muscle::public.muscle_group, v.secondary::public.muscle_group[], v.equipment::public.exercise_equipment,
  v.tracking::public.exercise_tracking, v.category::public.exercise_category, v.instructions, null
from (values
  -- Dehnen: Brust
  ('Brustdehnung im Türrahmen', 'chest', '{shoulders}', 'bodyweight', 'time', 'stretching', 'Unterarm auf Schulterhöhe an den Türrahmen legen, einen Schritt nach vorn gehen und den Oberkörper leicht wegdrehen, bis es in der Brust zieht. 30 s je Seite.'),
  ('Brustdehnung hoch (kleiner Brustmuskel)', 'chest', '{shoulders}', 'bodyweight', 'time', 'stretching', 'Ellbogen deutlich über Schulterhöhe an den Türrahmen legen und den Oberkörper nach vorn unten schieben. Zieht weiter oben Richtung Schulter, gut bei nach vorn gezogenen Schultern. 30 s je Seite.'),
  ('Brustöffner mit Händen hinter dem Rücken', 'chest', '{shoulders,biceps}', 'bodyweight', 'time', 'stretching', 'Hände hinter dem Rücken verschränken, Arme strecken und leicht anheben, Brustbein nach vorn oben schieben. Nicht ins Hohlkreuz fallen. 30 s halten.'),
  -- Dehnen: Rücken
  ('Kindhaltung (Rückendehnung)', 'back', '{shoulders,glutes}', 'bodyweight', 'time', 'stretching', 'Aus dem Knien das Gesäß zu den Fersen senken, Arme weit nach vorn strecken, Stirn ablegen und ruhig in den Rücken atmen. 45 s halten.'),
  ('Latissimus-Dehnung an der Stange', 'back', '{shoulders}', 'bodyweight', 'time', 'stretching', 'Mit beiden Händen eine Stange oder einen Türrahmen auf Hüfthöhe greifen, Gesäß nach hinten schieben und Arme lang lassen, bis es seitlich am Rücken zieht. 30 s halten.'),
  ('Katze-Kuh', 'back', '{core}', 'bodyweight', 'bodyweight_reps', 'stretching', 'Im Vierfüßlerstand beim Ausatmen den Rücken rund machen, beim Einatmen ins leichte Hohlkreuz gehen und den Blick heben. Langsam, 8 bis 10 Wiederholungen.'),
  ('Brustwirbelsäule drehen (Open Book)', 'back', '{chest,shoulders}', 'bodyweight', 'bodyweight_reps', 'stretching', 'In Seitlage die Knie anbeugen, Arme nach vorn. Oberen Arm im Bogen zur anderen Seite öffnen und mit dem Blick folgen, Knie bleiben zusammen. 8 Wiederholungen je Seite.'),
  ('Brustwirbelsäule über Faszienrolle strecken', 'back', '{shoulders}', 'other', 'time', 'stretching', 'Rolle quer unter den oberen Rücken legen, Hände stützen den Kopf, Gesäß bleibt am Boden. Oberkörper über die Rolle nach hinten sinken lassen und einige Stellen durchgehen. Nicht am unteren Rücken. 60 s.'),
  ('Knie zur Brust (unterer Rücken)', 'back', '{glutes}', 'bodyweight', 'time', 'stretching', 'Auf dem Rücken liegen, beide Knie mit den Händen zur Brust ziehen, unteren Rücken locker lassen. 30 s halten.'),
  ('Liegende Drehdehnung (Wirbelsäule)', 'back', '{glutes,core}', 'bodyweight', 'time', 'stretching', 'Auf dem Rücken die gebeugten Knie zu einer Seite sinken lassen, Schultern bleiben am Boden, Blick zur anderen Seite. 30 s je Seite.'),
  -- Dehnen: Schultern
  ('Schulterdehnung quer vor der Brust', 'shoulders', '{back}', 'bodyweight', 'time', 'stretching', 'Gestreckten Arm vor der Brust zur anderen Seite ziehen, Schulter dabei tief halten. Dehnt die hintere Schulter. 30 s je Seite.'),
  ('Sleeper Stretch (Schulter-Innenrotation)', 'shoulders', '{}', 'bodyweight', 'time', 'stretching', 'Auf der zu dehnenden Seite liegen, Oberarm und Ellbogen im rechten Winkel. Unterarm mit der anderen Hand sanft Richtung Boden drücken. Vorsichtig, bei Schmerz im Gelenk aufhören. 30 s je Seite.'),
  ('Schulterdehnung mit Handtuch hinter dem Rücken', 'shoulders', '{triceps}', 'other', 'time', 'stretching', 'Handtuch hinter dem Rücken mit einer Hand von oben und der anderen von unten greifen. Erst mit der oberen Hand sanft nach oben ziehen, dann mit der unteren nach unten. 30 s je Seite.'),
  ('Wandengel (Wall Angels)', 'shoulders', '{back}', 'bodyweight', 'bodyweight_reps', 'stretching', 'Mit Rücken, Kopf und Armen an die Wand stellen, Arme wie ein Torpfosten. Arme langsam nach oben und zurück schieben, ohne dass unterer Rücken oder Hände die Wand verlassen. 8 bis 10 Wiederholungen.'),
  ('Schulter-Dislocates mit Band', 'shoulders', '{chest}', 'band', 'bodyweight_reps', 'stretching', 'Band breit greifen und die gestreckten Arme langsam über den Kopf bis hinter den Körper führen und zurück. Griff so breit wählen, dass es ohne Hohlkreuz geht. 10 Wiederholungen.'),
  ('Hängen an der Stange (Dead Hang)', 'shoulders', '{back,forearms}', 'bodyweight', 'time', 'stretching', 'An einer Klimmzugstange hängen, Füße frei oder am Boden abgestützt, und ruhig atmen. Schultern und Rücken dürfen sich lang machen. 20 bis 40 s.'),
  -- Dehnen: Nacken
  ('Nackendehnung seitlich', 'neck', '{shoulders}', 'bodyweight', 'time', 'stretching', 'Aufrecht sitzen, Ohr Richtung Schulter neigen, die andere Schulter aktiv nach unten schieben. Hand darf leicht auf dem Kopf liegen, nicht ziehen. 30 s je Seite.'),
  ('Schulterblattheber-Dehnung (Nacken)', 'neck', '{shoulders}', 'bodyweight', 'time', 'stretching', 'Kopf zur Seite drehen und das Kinn Richtung Achsel senken, mit der Hand sanft führen, andere Schulter tief halten. Zieht hinten seitlich am Nacken. 30 s je Seite.'),
  ('Vordere Halsdehnung (Treppenmuskeln)', 'neck', '{}', 'bodyweight', 'time', 'stretching', 'Schulter tief halten, Kopf zur Gegenseite neigen und das Kinn etwas anheben. Ganz sanft, bei Schwindel oder Kribbeln sofort aufhören. 20 s je Seite.'),
  -- Dehnen: Arme
  ('Bizepsdehnung an der Wand', 'biceps', '{chest,forearms}', 'bodyweight', 'time', 'stretching', 'Handfläche auf Schulterhöhe hinter dem Körper an die Wand legen, Arm gestreckt, Oberkörper von der Wand wegdrehen. 30 s je Seite.'),
  ('Trizepsdehnung über Kopf', 'triceps', '{shoulders}', 'bodyweight', 'time', 'stretching', 'Arm nach oben nehmen, Ellbogen beugen und die Hand zwischen die Schulterblätter führen. Mit der anderen Hand den Ellbogen sanft nach hinten drücken. 30 s je Seite.'),
  ('Unterarmbeuger-Dehnung', 'forearms', '{}', 'bodyweight', 'time', 'stretching', 'Arm nach vorn strecken, Handfläche nach vorn, Finger nach unten. Mit der anderen Hand die Finger sanft Richtung Körper ziehen. 30 s je Seite.'),
  ('Unterarmstrecker-Dehnung', 'forearms', '{}', 'bodyweight', 'time', 'stretching', 'Arm nach vorn strecken, Handrücken nach vorn, Finger nach unten. Mit der anderen Hand den Handrücken sanft Richtung Körper ziehen. 30 s je Seite.'),
  ('Handgelenk-Dehnung im Vierfüßlerstand', 'forearms', '{}', 'bodyweight', 'time', 'stretching', 'Im Vierfüßlerstand die Finger Richtung Knie drehen, Handflächen bleiben am Boden, Gewicht langsam nach hinten verlagern. 30 s.'),
  -- Dehnen: Bauch
  ('Kobra (Bauchdehnung)', 'core', '{back,hip_flexors}', 'bodyweight', 'time', 'stretching', 'In Bauchlage mit den Händen neben der Brust den Oberkörper hochdrücken, Hüfte bleibt am Boden, Schultern tief. Nur so weit, wie der untere Rücken schmerzfrei bleibt. 20 bis 30 s.'),
  ('Seitliche Rumpfdehnung im Stehen', 'core', '{back}', 'bodyweight', 'time', 'stretching', 'Hüftbreit stehen, einen Arm über den Kopf nehmen und den Oberkörper zur Seite neigen, ohne nach vorn zu kippen. Dehnt Flanke und seitlichen Rücken. 30 s je Seite.'),
  -- Dehnen: Hüftbeuger
  ('Hüftbeuger-Dehnung im Halbkniestand', 'hip_flexors', '{quads}', 'bodyweight', 'time', 'stretching', 'In den Halbkniestand gehen, Gesäß anspannen und Becken aufrichten, dann die Hüfte leicht nach vorn schieben. Zieht vorn an der Hüfte des hinteren Beins. 30 bis 45 s je Seite.'),
  ('Couch Stretch', 'hip_flexors', '{quads}', 'bodyweight', 'time', 'stretching', 'Hinteren Fuß auf Sofa oder Bank ablegen, Knie davor am Boden, anderer Fuß vorn aufgestellt. Oberkörper aufrichten, Gesäß anspannen. Intensiv, langsam herantasten. 30 bis 60 s je Seite.'),
  ('Hüftbeuger-Dehnung an der Bankkante', 'hip_flexors', '{quads}', 'other', 'time', 'stretching', 'An der Bankkante auf den Rücken legen, ein Knie zur Brust ziehen und das andere Bein locker über die Kante hängen lassen. 30 s je Seite.'),
  -- Dehnen: Beinstrecker
  ('Quadrizeps-Dehnung im Stehen', 'quads', '{hip_flexors}', 'bodyweight', 'time', 'stretching', 'Aufrecht stehen, Fuß zum Gesäß ziehen, Knie bleiben nebeneinander, Becken leicht aufrichten. Bei Bedarf festhalten. 30 s je Seite.'),
  ('Quadrizeps-Dehnung in Seitlage', 'quads', '{hip_flexors}', 'bodyweight', 'time', 'stretching', 'Auf der Seite liegen, oberen Fuß mit der Hand zum Gesäß ziehen, Hüfte nach vorn schieben, nicht ins Hohlkreuz. 30 s je Seite.'),
  -- Dehnen: Beinbeuger
  ('Beinbeuger-Dehnung im Sitzen', 'hamstrings', '{back}', 'bodyweight', 'time', 'stretching', 'Sitzen, ein Bein gestreckt, der andere Fuß innen am Oberschenkel. Mit geradem Rücken aus der Hüfte nach vorn neigen. 30 s je Seite.'),
  ('Beinbeuger-Dehnung liegend mit Band', 'hamstrings', '{calves}', 'band', 'time', 'stretching', 'Auf dem Rücken liegen, Band um den Fuß legen und das gestreckte Bein langsam anheben, bis es hinten am Oberschenkel zieht. Das andere Bein bleibt am Boden. 30 s je Seite.'),
  ('Beinbeuger-Dehnung im Stehen', 'hamstrings', '{calves}', 'bodyweight', 'time', 'stretching', 'Ferse auf einer niedrigen Erhöhung abstellen, Bein gestreckt, Zehen heranziehen und mit geradem Rücken aus der Hüfte nach vorn neigen. 30 s je Seite.'),
  ('Stehende Vorbeuge', 'hamstrings', '{back,calves}', 'bodyweight', 'time', 'stretching', 'Hüftbreit stehen, Knie minimal beugen, Oberkörper aus der Hüfte nach vorn hängen lassen, Kopf und Arme locker. Zum Aufrichten die Knie beugen. 30 s.'),
  -- Dehnen: Gesäß
  ('Taube (Gesäßdehnung)', 'glutes', '{hip_flexors}', 'bodyweight', 'time', 'stretching', 'Aus dem Vierfüßlerstand ein Knie nach vorn zwischen die Hände ziehen, Unterschenkel schräg ablegen, anderes Bein lang nach hinten. Oberkörper langsam sinken lassen. Das Knie muss schmerzfrei bleiben. 45 s je Seite.'),
  ('Figur-4-Dehnung liegend', 'glutes', '{}', 'bodyweight', 'time', 'stretching', 'Auf dem Rücken einen Fußknöchel auf das andere Knie legen und den Oberschenkel des unteren Beins zur Brust ziehen. 30 s je Seite.'),
  ('Piriformis-Dehnung (Knie zur Gegenschulter)', 'glutes', '{}', 'bodyweight', 'time', 'stretching', 'Auf dem Rücken liegen und ein Knie mit beiden Händen Richtung gegenüberliegende Schulter ziehen. Zieht tief im Gesäß. 30 s je Seite.'),
  ('Hüftaußenseite-Dehnung im Stehen (Tractus)', 'glutes', '{}', 'bodyweight', 'time', 'stretching', 'Ein Bein hinter dem anderen kreuzen und die Hüfte dieser Seite nach außen schieben. Arm derselben Seite über den Kopf nehmen und den Oberkörper zur Gegenseite neigen. 30 s je Seite.'),
  ('90/90-Hüftdehnung', 'glutes', '{adductors,hip_flexors}', 'bodyweight', 'time', 'stretching', 'Am Boden sitzen, vorderes und hinteres Bein jeweils im rechten Winkel gebeugt. Mit geradem Rücken über das vordere Schienbein neigen. Für Innen- und Außenrotation der Hüfte. 45 s je Seite.'),
  -- Dehnen: Adduktoren
  ('Schmetterling (Adduktorendehnung)', 'adductors', '{}', 'bodyweight', 'time', 'stretching', 'Sitzen, Fußsohlen zusammen, Füße nah zum Körper. Aufrichten und die Knie langsam Richtung Boden sinken lassen, nicht wippen. 30 bis 45 s.'),
  ('Froschhaltung (Adduktorendehnung)', 'adductors', '{glutes}', 'bodyweight', 'time', 'stretching', 'Im Vierfüßlerstand die Knie weit öffnen, Innenkanten der Füße am Boden, Knie polstern. Hüfte langsam nach hinten schieben. 45 s.'),
  ('Seitlicher Ausfallschritt (Cossack Stretch)', 'adductors', '{glutes,hamstrings}', 'bodyweight', 'bodyweight_reps', 'stretching', 'Breit stehen und zu einer Seite in die Hocke gehen, das andere Bein gestreckt mit den Zehen nach oben. Die Ferse des gebeugten Beins bleibt unten. 8 Wiederholungen je Seite.'),
  ('Grätsche im Sitzen', 'adductors', '{hamstrings}', 'bodyweight', 'time', 'stretching', 'Sitzen, Beine weit gegrätscht, Zehen nach oben. Mit geradem Rücken aus der Hüfte nach vorn neigen. 30 bis 45 s.'),
  -- Dehnen: Waden
  ('Wadendehnung an der Wand (Bein gestreckt)', 'calves', '{}', 'bodyweight', 'time', 'stretching', 'Hände an die Wand, ein Bein weit nach hinten, Knie gestreckt, Ferse am Boden. Hüfte nach vorn schieben. Für den großen Wadenmuskel. 30 s je Seite.'),
  ('Soleus-Dehnung an der Wand (Knie gebeugt)', 'calves', '{}', 'bodyweight', 'time', 'stretching', 'Für Shin Splints. Wie die Wadendehnung, aber das hintere Knie beugen, die Ferse bleibt am Boden. Zieht tiefer und weiter unten in der Wade. 30 s je Seite.'),
  ('Wadendehnung auf der Stufe', 'calves', '{feet}', 'bodyweight', 'time', 'stretching', 'Mit dem Vorfuß auf eine Stufe stellen, festhalten und die Fersen langsam unter die Stufenkante sinken lassen. 30 s.'),
  ('Knee to Wall (Sprunggelenk)', 'calves', '{shins,feet}', 'bodyweight', 'bodyweight_reps', 'stretching', 'Für Shin Splints. Fuß eine Handbreit vor die Wand stellen und das Knie über die Zehen zur Wand schieben, die Ferse bleibt unten. Abstand langsam steigern. 10 Wiederholungen je Seite.'),
  -- Dehnen: Schienbein und Füße
  ('Schienbein-Dehnung im Knien', 'shins', '{feet}', 'bodyweight', 'time', 'stretching', 'Für Shin Splints. Auf den Fersen sitzen, Fußrücken flach am Boden, Hände hinter dem Körper abstützen und die Knie leicht anheben, bis es vorn am Schienbein zieht. Nur schmerzfrei. 30 s.'),
  ('Schienbein-Dehnung im Stehen', 'shins', '{feet}', 'bodyweight', 'time', 'stretching', 'Für Shin Splints. Aufrecht stehen, die Zehen eines Fußes hinter dem Körper aufstellen, Fußrücken Richtung Boden drücken und das Knie leicht nach vorn schieben. 30 s je Seite.'),
  ('Fußsohlen-Dehnung (Plantarfaszie)', 'feet', '{calves}', 'bodyweight', 'time', 'stretching', 'Im Sitzen einen Fuß aufs Knie legen und die Zehen mit der Hand zum Schienbein ziehen, bis es in der Fußsohle zieht. 30 s je Seite.'),
  ('Zehen-Dehnung im Fersensitz (Toe Sit)', 'feet', '{}', 'bodyweight', 'time', 'stretching', 'Im Fersensitz die Zehen aufstellen, sodass die Fußsohlen gedehnt werden. Gewicht langsam nach hinten verlagern, bei Bedarf mit den Händen abstützen. 20 bis 30 s.'),
  -- Dehnen: Ganzkörper
  ('World''s Greatest Stretch', 'full_body', '{hip_flexors,hamstrings,back}', 'bodyweight', 'bodyweight_reps', 'stretching', 'Großer Ausfallschritt, Hände am Boden. Den inneren Ellbogen zum vorderen Fuß senken, dann denselben Arm zur Decke aufdrehen und mit dem Blick folgen. 5 Wiederholungen je Seite.'),
  ('Herabschauender Hund', 'full_body', '{calves,hamstrings,shoulders}', 'bodyweight', 'time', 'stretching', 'Aus dem Vierfüßlerstand die Knie strecken und das Gesäß nach oben schieben, der Körper bildet ein umgedrehtes V. Fersen Richtung Boden sinken lassen. 30 bis 45 s.'),
  ('Tiefe Hocke halten', 'full_body', '{adductors,calves,glutes}', 'bodyweight', 'time', 'stretching', 'Fersen am Boden, in die tiefe Hocke sinken, Ellbogen schieben die Knie nach außen, Brust aufrecht. Bei Bedarf festhalten. 30 bis 60 s.'),
  -- Reha: Shin Splints (Schienbein, Waden, Füße, Hüfte)
  ('Tibialis Raises an der Wand', 'shins', '{}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Für Shin Splints. Mit dem Rücken an die Wand lehnen, Füße etwa 30 cm davor. Zehen langsam zum Schienbein heben und wieder senken, Fersen bleiben am Boden. 15 bis 20 Wiederholungen.'),
  ('Fußheben mit Band (Tibialis)', 'shins', '{feet}', 'band', 'bodyweight_reps', 'rehab', 'Für Shin Splints. Im Sitzen, Bein gestreckt, Band um den Fußrücken legen und vor dem Fuß befestigen. Zehen gegen den Zug zum Schienbein ziehen, langsam zurück. 15 Wiederholungen je Seite.'),
  ('Fersengang', 'shins', '{feet}', 'bodyweight', 'time', 'rehab', 'Für Shin Splints. Auf den Fersen gehen, Zehen und Vorfuß hochgezogen. Kurze Strecken, nur solange es schmerzfrei geht. 30 s.'),
  ('Zehenspitzengang', 'calves', '{feet}', 'bodyweight', 'time', 'rehab', 'Für Shin Splints. Auf den Zehenspitzen gehen, Fersen bleiben oben, Oberkörper aufrecht. 30 s.'),
  ('Fuß nach innen drehen mit Band', 'shins', '{feet}', 'band', 'bodyweight_reps', 'rehab', 'Für Shin Splints, stärkt den hinteren Schienbeinmuskel. Im Sitzen Band außen neben dem Fuß befestigen und um den Vorfuß legen. Fuß gegen den Zug nach innen oben führen, langsam zurück. 15 Wiederholungen je Seite.'),
  ('Fuß nach außen drehen mit Band', 'shins', '{feet}', 'band', 'bodyweight_reps', 'rehab', 'Für Shin Splints, stärkt die Wadenbeinmuskeln und stabilisiert das Sprunggelenk. Im Sitzen Band innen neben dem Fuß befestigen, Fuß gegen den Zug nach außen führen, langsam zurück. 15 Wiederholungen je Seite.'),
  ('Exzentrisches Wadenheben an der Stufe', 'calves', '{feet}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Für Shin Splints und Achillessehne. Vorfuß auf der Stufe, mit beiden Beinen hochdrücken und auf einem Bein in 3 bis 4 s absenken. 10 bis 15 Wiederholungen je Seite.'),
  ('Wadenheben mit gebeugtem Knie (Soleus)', 'calves', '{}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Für Shin Splints. Im Stand die Knie leicht gebeugt lassen und die Fersen heben, oben kurz halten, langsam absenken. Trainiert den Schollenmuskel, der beim Laufen viel Last aufnimmt. 15 bis 20 Wiederholungen.'),
  ('Einbeinstand (Balance)', 'feet', '{calves,glutes}', 'bodyweight', 'time', 'rehab', 'Für Shin Splints. Auf einem Bein stehen, Knie minimal gebeugt, Becken gerade. Schwerer mit geschlossenen Augen oder auf weichem Untergrund. 30 s je Seite.'),
  ('Handtuch mit den Zehen greifen', 'feet', '{}', 'other', 'bodyweight_reps', 'rehab', 'Für Shin Splints und das Fußgewölbe. Handtuch flach vor die Füße legen und es mit den Zehen heranziehen, die Ferse bleibt am Boden. 10 bis 15 Wiederholungen je Fuß.'),
  ('Short Foot (Fußgewölbe aktivieren)', 'feet', '{}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Für Shin Splints und Senkfüße. Im Stehen Ballen Richtung Ferse ziehen, sodass das Längsgewölbe höher wird, ohne die Zehen zu krallen. 5 s halten, 10 Wiederholungen.'),
  ('Fuß-Alphabet (Sprunggelenk)', 'feet', '{shins,calves}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Im Sitzen mit angehobenem Fuß das Alphabet in die Luft schreiben, nur aus dem Sprunggelenk. Gut für Shin Splints, nach dem Umknicken und zum Aufwärmen. Ein Durchgang je Fuß.'),
  ('Faszienrolle Wade', 'calves', '{}', 'other', 'time', 'rehab', 'Für Shin Splints. Wade auf die Rolle legen und langsam vom Knie bis kurz über die Achillessehne rollen, an empfindlichen Stellen kurz bleiben. 60 s je Seite.'),
  ('Faszienrolle Schienbeinmuskel', 'shins', '{}', 'other', 'time', 'rehab', 'Für Shin Splints. Im Vierfüßlerstand den Muskel außen neben der Schienbeinkante auf die Rolle legen und langsam rollen. Nie direkt auf dem Knochen. 45 s je Seite.'),
  ('Muschel (Clamshell)', 'glutes', '{}', 'band', 'bodyweight_reps', 'rehab', 'Für Shin Splints und Kniebeschwerden, stärkt die seitliche Hüfte. In Seitlage, Knie gebeugt, optional mit Band, das obere Knie öffnen. Füße bleiben zusammen, Becken kippt nicht. 15 Wiederholungen je Seite.'),
  ('Seitliches Beinheben liegend', 'glutes', '{}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Für Shin Splints und eine stabile Hüfte beim Laufen. In Seitlage das untere Bein beugen, das obere gestreckt und leicht nach hinten anheben, Zehen zeigen nach vorn. 15 Wiederholungen je Seite.'),
  ('Monster Walk mit Band', 'glutes', '{quads}', 'band', 'bodyweight_reps', 'rehab', 'Für Shin Splints und Kniebeschwerden. Band um die Oberschenkel oder Fußgelenke, leicht in die Knie gehen und seitlich oder schräg vorwärts gehen. Spannung halten, Knie nicht nach innen. 10 bis 15 Schritte je Richtung.'),
  -- Reha: Knie und Leiste
  ('Wandsitz (Wall Sit)', 'quads', '{glutes}', 'bodyweight', 'time', 'rehab', 'Bei gereizten Knien. Mit dem Rücken an der Wand in die Hocke rutschen, nur so tief, wie das Knie schmerzfrei bleibt. 30 bis 45 s.'),
  ('Terminal Knee Extension mit Band', 'quads', '{}', 'band', 'bodyweight_reps', 'rehab', 'Bei Läuferknie. Band hinter dem Knie an einem festen Punkt befestigen und das leicht gebeugte Knie gegen den Zug ganz strecken, kurz halten. 15 Wiederholungen je Seite.'),
  ('Step-downs von der Stufe', 'quads', '{glutes}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Bei Läuferknie. Auf einer niedrigen Stufe stehen und das andere Bein langsam senken, bis die Ferse den Boden berührt. Das Knie darf nicht nach innen fallen. 10 Wiederholungen je Seite.'),
  ('Copenhagen Plank', 'adductors', '{core}', 'bodyweight', 'time', 'rehab', 'Beugt Leistenproblemen vor. Seitstütz, oberes Bein auf einer Bank, unteres frei. Leichter mit dem Knie statt dem Fuß auf der Bank. 15 bis 30 s je Seite.'),
  -- Reha: Unterarme
  ('Exzentrische Handgelenkstreckung (Tennisarm)', 'forearms', '{}', 'dumbbell', 'weight_reps', 'rehab', 'Bei Tennisarm. Unterarm auflegen, Handfläche nach unten, leichte Hantel. Mit der anderen Hand nach oben helfen und in 3 bis 4 s absenken. 15 Wiederholungen je Seite.'),
  ('Exzentrische Handgelenkbeugung (Golferarm)', 'forearms', '{}', 'dumbbell', 'weight_reps', 'rehab', 'Bei Golferarm. Unterarm auflegen, Handfläche nach oben, leichte Hantel. Mit der anderen Hand nach oben helfen und in 3 bis 4 s absenken. 15 Wiederholungen je Seite.'),
  ('Finger spreizen mit Gummiband', 'forearms', '{}', 'band', 'bodyweight_reps', 'rehab', 'Gummiband um die Fingerspitzen legen und die Finger gegen den Zug spreizen. Gleicht das viele Greifen im Training aus. 15 bis 20 Wiederholungen.'),
  -- Reha: Schultern
  ('Außenrotation mit Band (Rotatorenmanschette)', 'shoulders', '{back}', 'band', 'bodyweight_reps', 'rehab', 'Ellbogen im rechten Winkel eng am Körper, Unterarm gegen das Band nach außen drehen, langsam zurück. 15 Wiederholungen je Seite.'),
  ('Innenrotation mit Band (Rotatorenmanschette)', 'shoulders', '{chest}', 'band', 'bodyweight_reps', 'rehab', 'Ellbogen im rechten Winkel eng am Körper, Unterarm gegen das Band nach innen zum Bauch drehen, langsam zurück. 15 Wiederholungen je Seite.'),
  ('Band Pull-Aparts', 'shoulders', '{back}', 'band', 'bodyweight_reps', 'rehab', 'Band mit gestreckten Armen auf Brusthöhe auseinanderziehen, Schulterblätter zusammenführen, langsam zurück. 15 bis 20 Wiederholungen.'),
  ('Y-T-W-Heben', 'shoulders', '{back}', 'bodyweight', 'bodyweight_reps', 'rehab', 'In Bauchlage oder vorgebeugt die Arme nacheinander als Y, T und W anheben, Schulterblätter nach hinten unten ziehen. Je Buchstabe 8 bis 10 Wiederholungen.'),
  ('Liegestütz-Plus (Serratus)', 'shoulders', '{chest,core}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Im Liegestütz mit gestreckten Armen die Schulterblätter zusammensinken lassen und dann weit auseinanderschieben, die Arme bleiben gestreckt. 10 bis 15 Wiederholungen.'),
  -- Reha: Rücken und Nacken
  ('Bird Dog', 'core', '{back,glutes}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Für einen stabilen unteren Rücken. Im Vierfüßlerstand den gegenüberliegenden Arm und das Bein strecken, Rumpf ruhig halten, kurz halten. 8 bis 10 Wiederholungen je Seite.'),
  ('McGill Curl-up', 'core', '{}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Für einen stabilen unteren Rücken. In Rückenlage ein Bein beugen, Hände unter den unteren Rücken. Kopf und Schultern minimal anheben, 5 bis 10 s halten, der Rücken bewegt sich nicht. 5 bis 8 Wiederholungen je Seite.'),
  ('Beckenkippen in Rückenlage', 'back', '{core}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Lockert den unteren Rücken. In Rückenlage mit angewinkelten Beinen den unteren Rücken sanft an den Boden drücken und wieder lösen. Langsam, 10 bis 15 Wiederholungen.'),
  ('Kinn zurückziehen (Chin Tucks)', 'neck', '{}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Gegen den vorgeschobenen Kopf am Schreibtisch. Aufrecht sitzen und den Kopf waagerecht nach hinten schieben, bis ein leichtes Doppelkinn entsteht. 5 s halten, 10 Wiederholungen.'),
  ('Nacken isometrisch (Hand gegen Kopf)', 'neck', '{}', 'bodyweight', 'bodyweight_reps', 'rehab', 'Hand an Stirn, Schläfe oder Hinterkopf legen und den Kopf sanft dagegen drücken, ohne dass er sich bewegt. Je Richtung 5 bis 10 s halten, 5 Wiederholungen.')
